def reverse_words_in_place(s):
    def reverse(left, right):
        while left < right:
            s[left],s[right] = s[right],s[left]
            left += 1
            right -= 1
    reverse(0,len(s)-1)
    start = 0
    for end in range(len(s)+1):
        if end == len(s) or s[end] == ' ':
            reverse(start,end-1)
            start = end+1

